source = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells4 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    cells6 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not cells4 or not cells6:
        return out
    r0, r1 = min(r for r, c in cells4), max(r for r, c in cells4)
    c0, c1 = min(c for r, c in cells4), max(c for r, c in cells4)
    mr = sum(r for r, c in cells6) / len(cells6)
    mc = sum(c for r, c in cells6) / len(cells6)
    sr, sc = (r0 + r1) / 2, (c0 + c1) / 2
    # The marker's side selects the reflection direction.
    dr, dc = mr - sr, mc - sc
    if abs(dr) >= abs(dc):
        if dr >= 0:
            for r, c in cells4:
                rr = r1 + 1 + (r1 - r)
                if rr < h:
                    out[rr][c] = 4
        else:
            for r, c in cells4:
                rr = r0 - 1 - (r - r0)
                if rr >= 0:
                    out[rr][c] = 4
    else:
        if dc >= 0:
            for r, c in cells4:
                cc = c1 + 1 + (c1 - c)
                if cc < w:
                    out[r][cc] = 4
        else:
            for r, c in cells4:
                cc = c0 - 1 - (c - c0)
                if cc >= 0:
                    out[r][cc] = 4
    for r, c in cells6:
        out[r][c] = 0
    return out
'''
